mapper.select:
SELECT 1 - (r.refund_cnt + n.no_show_cnt) / NULLIF(t.total_cnt, 0) FROM ( SELECT COUNT(1) AS total_cnt FROM TR_OUTP_FIN_CLINIC_MASTER c INNER JOIN TR_DEPT_DICT d ON c.dept_code = d.dept_code WHERE c.stat_date BETWEEN #{startDate} AND #{endDate}
) t, ( SELECT COUNT(1) AS refund_cnt FROM TR_OUTP_FIN_CLINIC_MASTER c INNER JOIN TR_DEPT_DICT d ON c.dept_code = d.dept_code WHERE c.returned_date BETWEEN #{startDate} AND #{endDate}
) r, ( SELECT COUNT(1) AS no_show_cnt FROM ( SELECT TRUNC(q.stat_date) AS dd, NVL(TO_CHAR(q.id_no), 'Q' || q.visit_no) AS k FROM TR_OUTP_FIN_MOP_QUEUE q LEFT JOIN TR_OUTP_FIN_CLINIC_MASTER cm ON cm.patient_id = q.patient_id AND cm.queue_num = q.queue_num WHERE q.appoints_indicator = 1 AND q.stat_date BETWEEN #{startDate} AND #{endDate} AND cm.patient_id IS NULL GROUP BY TRUNC(q.stat_date), NVL(TO_CHAR(q.id_no), 'Q' || q.visit_no) UNION ALL SELECT TRUNC(c2.stat_date) AS dd, NVL(c2.id_no, 'V' || c2.visit_no) AS k FROM TR_OUTP_FIN_CLINIC_MASTER c2 INNER JOIN TR_DEPT_DICT d ON c2.dept_code = d.dept_code WHERE c2.registration_status <= 1 AND c2.stat_date BETWEEN #{startDate} AND #{endDate}
GROUP BY TRUNC(c2.stat_date), NVL(c2.id_no, 'V' || c2.visit_no) ) ) n

SELECT TO_CHAR(w.weather_date, 'YYYY-MM-DD') AS dd, w.weather_coef AS num
FROM tr_fc_weather w
WHERE w.weather_date BETWEEN #{startDate} AND #{endDate}
